function ConvertTo-CompleteResults{
    param(
        [parameter(Mandatory, ValueFromPipeline,Position=0)][string[]]$Values,
        [string]$wordToComplete,
        [switch]$StartWith
    )

    begin {
        $pattern = $StartWith.IsPresent ? "$wordToComplete*" : "*$wordToComplete*"

        $list = @()
    }

    process{
        $list += $Values
    }

    end{

        "Processing $($list.Count) values for completion with pattern '$pattern'" | Write-Mydebug -Section "ArgumentCompleter"

        $ret = $list | Where-Object { $_ -like $pattern } | Select-Object -Unique
        
        "Returning $($ret.Count) values matching '$pattern'" | Write-Mydebug -Section "ArgumentCompleter" -object $ret

        $ret = $ret | addQuotesIfSpaces

        $ret | ForEach-Object { [System.Management.Automation.CompletionResult]::new( $_, $_, 'ParameterValue', $_) }
    }
}

function addQuotesIfSpaces {
    param(
        [parameter(Mandatory, ValueFromPipeline,Position=0)][string]$Value
    )

    process{

        if($Value -like "* *"){
            "Adding quotes to value '$Value'" | Write-Mydebug -Section "ArgumentCompleter"
            return "`"$Value`""
        }
        else{
            return $Value
        }
    }
}

# Parse CommandText to find the value of an already filled parameter.
# Checks for parameter alias too.
function getParameterValue {
    param(
        [System.Management.Automation.Language.CommandAst]$commandAst,
        [string]$ParameterName,
        [string]$ParameterAlias,
        [string]$ParameterPosition = "-1"
    )

    $CommandText = $commandAst.Extent.Text
    
    # Match parameter followed by either quoted string or unquoted word
    if ($CommandText -match "-$ParameterName\s+(?:(?:`"([^`"]*)`")|(?:'([^']*)')|([^\s-]+))") {
        $ret =  $matches[1], $matches[2], $matches[3] | Where-Object { $_ }
        "Found parameter '$ParameterName' with value '$ret'" | Write-Mydebug -Section "ArgumentCompleter"
        return $ret
    }
    
    # If ParameterName not found, try ParameterAlias
    if ($ParameterAlias -and $CommandText -match "-$ParameterAlias\s+(?:(?:`"([^`"]*)`")|(?:'([^']*)')|([^\s-]+))") {
        $ret = $matches[1], $matches[2], $matches[3] | Where-Object { $_ }
        "Found parameter '$ParameterAlias' with value '$ret'" | Write-Mydebug -Section "ArgumentCompleter"
        return $ret
    }

    # If ParameterName and ParameterAlias not found, try positional parameter
    if($ParameterPosition -ne "-1"){
        $Position = [int]$ParameterPosition
        $s = ($CommandText -split '\s+')
        
        # Remove the command name
        $s = @($s | Select-Object -Skip 1)

        if($s.Length -gt $Position){
            $ret = $s[$Position]
            "Found positional parameter at position $Position with value '$ret'" | Write-Mydebug
            return $ret
        }
    }
    
    return $null
}